__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"ATHKAR",{enumerable:!0,get:function(){return n}});const n=[{id:'a1',group:'Morning',name:'Morning Declaration',arabic:'\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650',transliteration:'Asbahna wa asbahal mulku lillahi',count:1},{id:'a2',group:'Morning',name:'SubhanAllahi wa bihamdihi',arabic:'\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650',transliteration:'Subhanallahi wa bihamdih',count:100,note:'Whoever says it 100 times a day, their sins are erased even if they were like the foam of the sea. (Bukhari & Muslim)'},{id:'a3',group:'Morning',name:'Refuge from the Shaytan',arabic:'\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u064e\u0651\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0627\u0644\u0631\u064e\u0651\u062c\u0650\u064a\u0645\u0650',transliteration:'Audhu billahi minash shaytanir rajim',count:3},{id:'a4',group:'Morning',name:'Ayat al-Kursi',arabic:'\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651 \u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0645\u064f',transliteration:'Allahu la ilaha illa Huwal Hayyul Qayyum',count:1,note:'Whoever recites it in the morning is protected until evening. (Abu Dawud)'},{id:'a5',group:'Morning',name:'As al-Allaha al-Azeem',arabic:'\u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064e \u0631\u064e\u0628\u064e\u0651 \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650',transliteration:'As al-Allaha al-Azeem Rabbal Arshil Azeem',count:1},{id:'a6',group:'Evening',name:'Evening Declaration',arabic:'\u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0645\u0652\u0633\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650',transliteration:'Amsayna wa amsal mulku lillahi',count:1},{id:'a7',group:'Evening',name:'Complete Words of Allah',arabic:'\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u062a\u064e\u0651\u0627\u0645\u064e\u0651\u0629\u0650',transliteration:'Audhu bikalimatillahit tammah',count:3},{id:'a8',group:'Evening',name:'Raditu billahi Rabba',arabic:'\u0631\u064e\u0636\u0650\u064a\u062a\u064f \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0631\u064e\u0628\u064b\u0651\u0627 \u0648\u064e\u0628\u0650\u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u062f\u0650\u064a\u0646\u064b\u0627 \u0648\u064e\u0628\u0650\u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \ufdfa \u0646\u064e\u0628\u0650\u064a\u064b\u0651\u0627',transliteration:'Raditu billahi Rabban wa bil-islami deena wa bi-Muhammadin \ufdfa nabiyya',count:3},{id:'a9',group:'After Prayer',name:'SubhanAllahi',arabic:'\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650',transliteration:'SubhanAllahi',count:33},{id:'a10',group:'After Prayer',name:'Alhamdulillah',arabic:'\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650',transliteration:'Alhamdulillah',count:33},{id:'a11',group:'After Prayer',name:'Allahu Akbar',arabic:'\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f',transliteration:'Allahu Akbar',count:34,note:'33 SubhanAllahi, 33 Alhamdulillah, 34 Allahu Akbar \u2014 completes 100 after the prayer. (Muslim)'},{id:'a12',group:'After Prayer',name:'Salam after Salah',arabic:'\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f',transliteration:'Allahumma antas Salamu wa minkas Salam',count:1},{id:'a13',group:'General',name:'Salawat upon the Prophet \ufdfa',arabic:'\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0635\u064e\u0644\u0650\u0651 \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d',transliteration:'Allahumma salli ala Muhammad',count:11},{id:'a14',group:'General',name:'Astaghfirullah',arabic:'\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e',transliteration:'Astaghfirullah',count:100},{id:'a15',group:'General',name:'La ilaha illallah',arabic:'\u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f',transliteration:'La ilaha illallah',count:0,note:'Custom dhikr runs in unlimited mode so you can keep counting without a target cap.'}]},1391,[]);
