__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"NAMES_99",{enumerable:!0,get:function(){return n}});const n=[{number:1,arabic:"\u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0646\u064f",transliteration:"Ar Rahmaan",translation:"The Most Merciful",meaning:"The One who has plenty of mercy for the believers and the blasphemers in this world and especially for the believers in the hereafter."},{number:2,arabic:"\u0627\u0644\u0631\u064e\u0651\u062d\u0650\u064a\u0645\u064f",transliteration:"Ar Raheem",translation:"The Most Compassionate",meaning:"The One who has plenty of mercy for the believers."},{number:3,arabic:"\u0627\u0644\u0652\u0645\u064e\u0644\u0650\u0643\u064f",transliteration:"Al Malik",translation:"The King",meaning:"The Sovereign Lord, The One who has absolute ownership and authority over all creation."},{number:4,arabic:"\u0627\u0644\u0652\u0642\u064f\u062f\u064f\u0651\u0648\u0633\u064f",transliteration:"Al Quddus",translation:"The Most Holy",meaning:"The One who is pure from any imperfection and clear from children and adversaries."},{number:5,arabic:"\u0627\u0644\u0633\u064e\u0651\u0644\u0627\u064e\u0645\u064f",transliteration:"As Salaam",translation:"The Source of Peace",meaning:"The One who grants peace and calm to all creation."},{number:6,arabic:"\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f",transliteration:"Al Mu'min",translation:"The Guardian of Faith",meaning:"The One who grants safety and security to His creation."},{number:7,arabic:"\u0627\u0644\u0652\u0645\u064f\u0647\u064e\u064a\u0652\u0645\u0650\u0646\u064f",transliteration:"Al Muhaymin",translation:"The Guardian",meaning:"The One who witnesses the saying and deeds of His creatures."},{number:8,arabic:"\u0627\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u064f",transliteration:"Al Azeez",translation:"The Almighty",meaning:"The strong, the defeater who is not defeated."},{number:9,arabic:"\u0627\u0644\u0652\u062c\u064e\u0628\u064e\u0651\u0627\u0631\u064f",transliteration:"Al Jabbaar",translation:"The Compeller",meaning:"The One that nothing happens in His dominion except that which He willed."},{number:10,arabic:"\u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0650\u0651\u0631\u064f",transliteration:"Al Mutakabbir",translation:"The Supreme",meaning:"The Supreme, The One who is supremely great and above all creation."},{number:11,arabic:"\u0627\u0644\u0652\u062e\u064e\u0627\u0644\u0650\u0642\u064f",transliteration:"Al Khaaliq",translation:"The Creator",meaning:"The One who brings everything from non-existence to existence."},{number:12,arabic:"\u0627\u0644\u0652\u0628\u064e\u0627\u0631\u0650\u0626\u064f",transliteration:"Al Baari",translation:"The Maker of Order",meaning:"The Maker, The Creator who has the power to materialize and proportion His creation."},{number:13,arabic:"\u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0648\u0650\u0651\u0631\u064f",transliteration:"Al Musawwir",translation:"The Shaper of Beauty",meaning:"The Fashioner, The One who forms His creatures in different shapes and forms."},{number:14,arabic:"\u0627\u0644\u0652\u063a\u064e\u0641\u064e\u0651\u0627\u0631\u064f",transliteration:"Al Ghaffaar",translation:"The Forgiving",meaning:"The One who forgives the sins of His slaves time and time again."},{number:15,arabic:"\u0627\u0644\u0652\u0642\u064e\u0647\u064e\u0651\u0627\u0631\u064f",transliteration:"Al Qahhaar",translation:"The Subduer",meaning:"The Subduer, The One who has perfect Power and absolute control over all things."},{number:16,arabic:"\u0627\u0644\u0652\u0648\u064e\u0647\u064e\u0651\u0627\u0628\u064f",transliteration:"Al Wahhaab",translation:"The Bestower",meaning:"The One who is Generous in giving plenty without any return."},{number:17,arabic:"\u0627\u0644\u0631\u064e\u0651\u0632\u064e\u0651\u0627\u0642\u064f",transliteration:"Ar Razzaaq",translation:"The Provider",meaning:"The One who provides all the creatures their needs."},{number:18,arabic:"\u0627\u0644\u0652\u0641\u064e\u062a\u064e\u0651\u0627\u062d\u064f",transliteration:"Al Fattaah",translation:"The Opener",meaning:"The One who opens for His slaves the closed worldly and religious matters."},{number:19,arabic:"\u0627\u064e\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0652\u0645\u064f",transliteration:"Al 'Aleem",translation:"The All-Knowing",meaning:"The One nothing is absent from His knowledge."},{number:20,arabic:"\u0627\u0644\u0652\u0642\u064e\u0627\u0628\u0650\u0636\u064f",transliteration:"Al Qaabid",translation:"The Constrictor",meaning:"The One who constricts the sustenance by His wisdom."},{number:21,arabic:"\u0627\u0644\u0652\u0628\u064e\u0627\u0633\u0650\u0637\u064f",transliteration:"Al Baasit",translation:"The Expander",meaning:"The One who expands and widens."},{number:22,arabic:"\u0627\u0644\u0652\u062e\u064e\u0627\u0641\u0650\u0636\u064f",transliteration:"Al Khaafid",translation:"The Abaser",meaning:"The One who lowers whoever He willed by His Destruction."},{number:23,arabic:"\u0627\u0644\u0631\u064e\u0651\u0627\u0641\u0650\u0639\u064f",transliteration:"Ar Raafi'",translation:"The Exalter",meaning:"The One who raises whoever He willed by His endowment."},{number:24,arabic:"\u0627\u0644\u0652\u0645\u064f\u0639\u0650\u0632\u064f\u0651",transliteration:"Al Mu'iz",translation:"The Bestower of Honour",meaning:"He gives esteem to whoever He willed, hence there is no one to degrade Him."},{number:25,arabic:"\u0627\u0644\u0645\u064f\u0630\u0650\u0644\u064f\u0651",transliteration:"Al Mudhil",translation:"The Humiliator",meaning:"The One who degrades whoever he willed, hence there is no one to give him esteem."},{number:26,arabic:"\u0627\u0644\u0633\u064e\u0651\u0645\u0650\u064a\u0639\u064f",transliteration:"As Samee'",translation:"The All-Hearing",meaning:"The One who Hears all things that are heard by His Eternal Hearing without an ear, instrument or organ."},{number:27,arabic:"\u0627\u0644\u0652\u0628\u064e\u0635\u0650\u064a\u0631\u064f",transliteration:"Al Baseer",translation:"The All-Seeing",meaning:"The One who Sees all things that are seen by His Eternal Seeing without a pupil or any other instrument."},{number:28,arabic:"\u0627\u0644\u0652\u062d\u064e\u0643\u064e\u0645\u064f",transliteration:"Al Hakam",translation:"The Judge",meaning:"The One who is the judge, the arbitrator, the One who has the complete authority to decide between the creatures."},{number:29,arabic:"\u0627\u0644\u0652\u0639\u064e\u062f\u0652\u0644\u064f",transliteration:"Al 'Adl",translation:"The Just",meaning:"The One who is entitled to do what He does."},{number:30,arabic:"\u0627\u0644\u0644\u064e\u0651\u0637\u0650\u064a\u0641\u064f",transliteration:"Al Lateef",translation:"The Subtle One",meaning:"The One who is kind to His slaves and endows upon them."},{number:31,arabic:"\u0627\u0644\u0652\u062e\u064e\u0628\u0650\u064a\u0631\u064f",transliteration:"Al Khabeer",translation:"The All-Aware",meaning:"The One who knows the truth of things."},{number:32,arabic:"\u0627\u0644\u0652\u062d\u064e\u0644\u0650\u064a\u0645\u064f",transliteration:"Al Haleem",translation:"The Forbearing",meaning:"The One who delays the punishment for those who deserve it and then He might forgive them."},{number:33,arabic:"\u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f",transliteration:"Al 'Azeem",translation:"The Magnificent",meaning:"The One deserving the attributes of Exaltment, Glory, Extolement, and complete Majesty."},{number:34,arabic:"\u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f",transliteration:"Al Ghafoor",translation:"The Great Forgiver",meaning:"The One who forgives a lot."},{number:35,arabic:"\u0627\u0644\u0634\u064e\u0651\u0643\u064f\u0648\u0631\u064f",transliteration:"Ash Shakoor",translation:"The Rewarder of Thankfulness",meaning:"The One who gives a lot of reward for a little obedience."},{number:36,arabic:"\u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u064f\u0651",transliteration:"Al 'Aliyy",translation:"The Most High",meaning:"The One who is clear from the attributes of the creatures."},{number:37,arabic:"\u0627\u0644\u0652\u0643\u064e\u0628\u0650\u064a\u0631\u064f",transliteration:"Al Kabeer",translation:"The Most Great",meaning:"The One who is greater than everything in status."},{number:38,arabic:"\u0627\u0644\u0652\u062d\u064e\u0641\u0650\u064a\u0638\u064f",transliteration:"Al Hafeez",translation:"The Preserver",meaning:"The One who protects whatever and whoever He willed to protect."},{number:39,arabic:"\u0627\u0644\u0645\u064f\u0642\u064a\u0650\u062a",transliteration:"Al Muqeet",translation:"The Nourisher",meaning:"The One who has the Power."},{number:40,arabic:"\u0627\u0644\u0652\u062d\u0633\u0650\u064a\u0628\u064f",transliteration:"Al Haseeb",translation:"The Reckoner",meaning:"The One who gives the satisfaction."},{number:41,arabic:"\u0627\u0644\u0652\u062c\u064e\u0644\u0650\u064a\u0644\u064f",transliteration:"Al Jaleel",translation:"The Majestic",meaning:"The One who is attributed with greatness of Power and Glory of status."},{number:42,arabic:"\u0627\u0644\u0652\u0643\u064e\u0631\u0650\u064a\u0645\u064f",transliteration:"Al Kareem",translation:"The Generous",meaning:"The One who is clear from abjectness."},{number:43,arabic:"\u0627\u0644\u0631\u064e\u0651\u0642\u0650\u064a\u0628\u064f",transliteration:"Ar Raqeeb",translation:"The Watchful One",meaning:"The One that nothing is absent from Him."},{number:44,arabic:"\u0627\u0644\u0652\u0645\u064f\u062c\u0650\u064a\u0628\u064f",transliteration:"Al Mujeeb",translation:"The Responder to Prayer",meaning:"The One who answers the one in need if he asks Him and rescues the yearner if he calls upon Him."},{number:45,arabic:"\u0627\u0644\u0652\u0648\u064e\u0627\u0633\u0650\u0639\u064f",transliteration:"Al Waasi'",translation:"The All-Encompassing",meaning:"The Knowledgeable; The One nothing is absent from His knowledge."},{number:46,arabic:"\u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f",transliteration:"Al Hakeem",translation:"The Perfectly Wise",meaning:"The One who is correct in His doings."},{number:47,arabic:"\u0627\u0644\u0652\u0648\u064e\u062f\u064f\u0648\u062f\u064f",transliteration:"Al Wudood",translation:"The Loving One",meaning:"The One who loves His believing slaves and His believing slaves love Him."},{number:48,arabic:"\u0627\u0644\u0652\u0645\u064e\u062c\u0650\u064a\u062f\u064f",transliteration:"Al Majeed",translation:"The Most Glorious One",meaning:"The One who is with perfect Power, High Status, Compassion, Generosity and Kindness."},{number:49,arabic:"\u0627\u0644\u0652\u0628\u064e\u0627\u0639\u0650\u062b\u064f",transliteration:"Al Baa'ith",translation:"The Resurrector",meaning:"The One who resurrects His slaves after death for reward and/or punishment."},{number:50,arabic:"\u0627\u0644\u0634\u064e\u0651\u0647\u0650\u064a\u062f\u064f",transliteration:"Ash Shaheed",translation:"The Witness",meaning:"The Witness, The One from whom nothing is hidden."},{number:51,arabic:"\u0627\u0644\u0652\u062d\u064e\u0642\u064f\u0651",transliteration:"Al Haqq",translation:"The Truth",meaning:"The One who truly exists."},{number:52,arabic:"\u0627\u0644\u0652\u0648\u064e\u0643\u0650\u064a\u0644\u064f",transliteration:"Al Wakeel",translation:"The Trustee",meaning:"The Trustee, The One who is relied upon for all affairs."},{number:53,arabic:"\u0627\u0644\u0652\u0642\u064e\u0648\u0650\u064a\u064f\u0651",transliteration:"Al Qawiyy",translation:"The Possessor of all strength",meaning:"The One with the complete Power."},{number:54,arabic:"\u0627\u0644\u0652\u0645\u064e\u062a\u0650\u064a\u0646\u064f",transliteration:"Al Mateen",translation:"The Forceful",meaning:"The Firm, The One with steadfast power who never tires."},{number:55,arabic:"\u0627\u0644\u0652\u0648\u064e\u0644\u0650\u064a\u064f\u0651",transliteration:"Al Waliyy",translation:"The Protector",meaning:"The Protecting Friend, The One who supports and manages the affairs of His servants."},{number:56,arabic:"\u0627\u0644\u0652\u062d\u064e\u0645\u0650\u064a\u062f\u064f",transliteration:"Al Hameed",translation:"The Praiseworthy",meaning:"The praised One who deserves to be praised."},{number:57,arabic:"\u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0635\u0650\u064a",transliteration:"Al Muhsi",translation:"The Reckoner",meaning:"The One who the count of things are known to him."},{number:58,arabic:"\u0627\u0644\u0652\u0645\u064f\u0628\u0652\u062f\u0650\u0626\u064f",transliteration:"Al Mubdi",translation:"The Originator",meaning:"The One who started the human being. That is, He created him."},{number:59,arabic:"\u0627\u0644\u0652\u0645\u064f\u0639\u0650\u064a\u062f\u064f",transliteration:"Al Mu'eed",translation:"The Restorer",meaning:"The One who brings back the creatures after death."},{number:60,arabic:"\u0627\u0644\u0652\u0645\u064f\u062d\u0652\u064a\u0650\u064a",transliteration:"Al Muhiy",translation:"The Giver of Life",meaning:"The One who took out a living human from semen that does not have a soul."},{number:61,arabic:"\u0627\u064e\u0644\u0652\u0645\u064f\u0645\u0650\u064a\u062a\u064f",transliteration:"Al Mumeet",translation:"The Bringer of Death",meaning:"The One who renders the living dead."},{number:62,arabic:"\u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651",transliteration:"Al Haiyy",translation:"The Ever-Living",meaning:"The One attributed with a life that is neither born nor is it coming to an end."},{number:63,arabic:"\u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0645\u064f",transliteration:"Al Qayyoom",translation:"The Self-Sustaining",meaning:"The One who remains and does not end."},{number:64,arabic:"\u0627\u0644\u0652\u0648\u064e\u0627\u062c\u0650\u062f\u064f",transliteration:"Al Waajid",translation:"The Finder",meaning:"The Rich who is never poor. Al-Wajd is Richness."},{number:65,arabic:"\u0627\u0644\u0652\u0645\u064e\u0627\u062c\u0650\u062f\u064f",transliteration:"Al Maajid",translation:"The Most Glorious",meaning:"The One who is Majid."},{number:66,arabic:"\u0627\u0644\u0652\u0648\u0627\u062d\u0650\u062f\u064f",transliteration:"Al Waahid",translation:"The Only One",meaning:"The One without a partner."},{number:67,arabic:"\u0627\u064e\u0644\u0627\u064e\u062d\u064e\u062f\u064f",transliteration:"Al Ahad",translation:"The Unique",meaning:"The One who is unique in His essence and attributes."},{number:68,arabic:"\u0627\u0644\u0635\u064e\u0651\u0645\u064e\u062f\u064f",transliteration:"As Samad",translation:"The Eternal",meaning:"The Master who is relied upon in matters and reverted to in ones needs."},{number:69,arabic:"\u0627\u0644\u0652\u0642\u064e\u0627\u062f\u0650\u0631\u064f",transliteration:"Al Qaadir",translation:"The Capable",meaning:"The One attributed with Power."},{number:70,arabic:"\u0627\u0644\u0652\u0645\u064f\u0642\u0652\u062a\u064e\u062f\u0650\u0631\u064f",transliteration:"Al Muqtadir",translation:"The Creator of all power",meaning:"The One with the perfect Power that nothing is withheld from Him."},{number:71,arabic:"\u0627\u0644\u0652\u0645\u064f\u0642\u064e\u062f\u0650\u0651\u0645\u064f",transliteration:"Al Muqaddim",translation:"The Expediter",meaning:"The One who puts things in their right place. He makes ahead what He wills."},{number:72,arabic:"\u0627\u0644\u0652\u0645\u064f\u0624\u064e\u062e\u0650\u0651\u0631\u064f",transliteration:"Al Mu'akhir",translation:"The Delayer",meaning:"The One who puts things in their right place. He makes behind what He wills."},{number:73,arabic:"\u0627\u0644\u0623\u0648\u064e\u0651\u0644\u064f",transliteration:"Al Awwal",translation:"The First",meaning:"The One whose Existence is without a beginning."},{number:74,arabic:"\u0627\u0644\u0622\u062e\u0650\u0631\u064f",transliteration:"Al Aakhir",translation:"The Last",meaning:"The One whose Existence is without an end."},{number:75,arabic:"\u0627\u0644\u0638\u064e\u0651\u0627\u0647\u0650\u0631\u064f",transliteration:"Az Zaahir",translation:"The Manifest",meaning:"The One that nothing is above Him and nothing is underneath Him, hence He exists without a place."},{number:76,arabic:"\u0627\u0644\u0652\u0628\u064e\u0627\u0637\u0650\u0646\u064f",transliteration:"Al Baatin",translation:"The Hidden",meaning:"The One that nothing is above Him and nothing is underneath Him, hence He exists without a place."},{number:77,arabic:"\u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u064a",transliteration:"Al Waali",translation:"The Governor",meaning:"The One who owns things and manages them."},{number:78,arabic:"\u0627\u0644\u0652\u0645\u064f\u062a\u064e\u0639\u064e\u0627\u0644\u0650\u064a",transliteration:"Al Muta'ali",translation:"The Self Exalted",meaning:"The One who is clear from the attributes of the creation."},{number:79,arabic:"\u0627\u0644\u0652\u0628\u064e\u0631\u064f\u0651",transliteration:"Al Barr",translation:"The Source of All Goodness",meaning:"The One who is kind to His creatures, who covered them with His sustenance and specified whoever He willed among them by His support, protection, and special mercy."},{number:80,arabic:"\u0627\u0644\u062a\u064e\u0651\u0648\u064e\u0627\u0628\u064f",transliteration:"At Tawwaab",translation:"The Acceptor of Repentance",meaning:"The One who grants repentance to whoever He willed among His creatures and accepts his repentance."},{number:81,arabic:"\u0627\u0644\u0652\u0645\u064f\u0646\u0652\u062a\u064e\u0642\u0650\u0645\u064f",transliteration:"Al Muntaqim",translation:"The Avenger",meaning:"The One who victoriously prevails over His enemies and punishes them for their sins."},{number:82,arabic:"\u0627\u0644\u0639\u064e\u0641\u064f\u0648\u064f\u0651",transliteration:"Al Afuww",translation:"The Pardoner",meaning:"The One with wide forgiveness."},{number:83,arabic:"\u0627\u0644\u0631\u064e\u0651\u0624\u064f\u0648\u0641\u064f",transliteration:"Ar Ra'oof",translation:"The Most Kind",meaning:"The One with extreme Mercy. The Mercy of Allah is His will to endow upon whoever He willed among His creatures."},{number:84,arabic:"\u0645\u064e\u0627\u0644\u0650\u0643\u064f \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u0650",transliteration:"Maalik Ul Mulk",translation:"Master of the Kingdom",meaning:"The One who controls the Dominion and gives dominion to whoever He willed."},{number:85,arabic:"\u0630\u064f\u0648\u0627\u0644\u0652\u062c\u064e\u0644\u0627\u064e\u0644\u0650 \u0648\u064e\u0627\u0644\u0625\u0643\u0652\u0631\u064e\u0627\u0645\u0650",transliteration:"Dhu Al Jalaali Wa Al Ikraam",translation:"Lord of Majesty and Bounty",meaning:"The One who deserves to be Exalted and not denied."},{number:86,arabic:"\u0627\u0644\u0652\u0645\u064f\u0642\u0652\u0633\u0650\u0637\u064f",transliteration:"Al Muqsit",translation:"The Equitable",meaning:"The One who is Just in His judgment."},{number:87,arabic:"\u0627\u0644\u0652\u062c\u064e\u0627\u0645\u0650\u0639\u064f",transliteration:"Al Jaami'",translation:"The Gatherer",meaning:"The One who gathers the creatures on a day that there is no doubt about, that is the Day of Judgment."},{number:88,arabic:"\u0627\u0644\u0652\u063a\u064e\u0646\u0650\u064a\u064f\u0651",transliteration:"Al Ghaniyy",translation:"The Self-Sufficient",meaning:"The One who does not need the creation."},{number:89,arabic:"\u0627\u0644\u0652\u0645\u064f\u063a\u0652\u0646\u0650\u064a",transliteration:"Al Mughi",translation:"The Enricher",meaning:"The One who satisfies the necessities of the creatures."},{number:90,arabic:"\u0627\u064e\u0644\u0652\u0645\u064e\u0627\u0646\u0650\u0639\u064f",transliteration:"Al Maani'",translation:"The Preventer of harm",meaning:"The Supporter who protects and gives victory to His pious believers."},{number:91,arabic:"\u0627\u0644\u0636\u064e\u0651\u0627\u0631\u064e\u0651",transliteration:"Ad Daaarr",translation:"The Harmer",meaning:"The One who makes harm reach to whoever He willed and benefit to whoever He willed."},{number:92,arabic:"\u0627\u0644\u0646\u064e\u0651\u0627\u0641\u0650\u0639\u064f",transliteration:"An Naafi'",translation:"The Benefactor",meaning:"The One who gives benefit to whoever He willed."},{number:93,arabic:"\u0627\u0644\u0646\u064f\u0651\u0648\u0631\u064f",transliteration:"An Noor",translation:"The Light",meaning:"The One who guides."},{number:94,arabic:"\u0627\u0644\u0652\u0647\u064e\u0627\u062f\u0650\u064a",transliteration:"Al Haadi",translation:"The Guider",meaning:"The One who guides."},{number:95,arabic:"\u0627\u0644\u0652\u0628\u064e\u062f\u0650\u064a\u0639\u064f",transliteration:"Al Badi'",translation:"The Incomparable Originator",meaning:"The One who created the creation and formed it without any preceding example."},{number:96,arabic:"\u0627\u064e\u0644\u0652\u0628\u064e\u0627\u0642\u0650\u064a",transliteration:"Al Baaqi",translation:"The Everlasting One",meaning:"The One that the state of non-existence is impossible for Him."},{number:97,arabic:"\u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u064f",transliteration:"Al Waarith",translation:"The Inheritor",meaning:"The One whose Existence remains."},{number:98,arabic:"\u0627\u0644\u0631\u064e\u0651\u0634\u0650\u064a\u062f\u064f",transliteration:"Ar Rasheed",translation:"The Most Righteous Guide",meaning:"The One who guides."},{number:99,arabic:"\u0627\u0644\u0635\u064e\u0651\u0628\u064f\u0648\u0631\u064f",transliteration:"As Saboor",translation:"The Patient One",meaning:"The One who does not quickly punish the sinners."}]},1421,[]);
